extends Node
class_name VisualReadinessGate

signal readiness_changed(report: Dictionary)

var last_report: Dictionary = {}

func evaluate(using_real_osm: bool) -> Dictionary:
    var vehicles := {}
    for vehicle_id in ["taxi_01", "louage_01", "pickup_01", "pickup_404"]:
        vehicles[vehicle_id] = not VehicleVisualCatalog.resolve_scene_path(vehicle_id).is_empty()

    var player_real := not PlayerVisualCatalog.resolve_scene_path().is_empty()
    var real_vehicle_count := 0
    for value in vehicles.values():
        if bool(value):
            real_vehicle_count += 1

    last_report = {
        "real_osm": using_real_osm,
        "real_player_asset": player_real,
        "real_vehicle_count": real_vehicle_count,
        "vehicle_assets": vehicles,
        "visual_milestone_pass": (
            using_real_osm
            and player_real
            and real_vehicle_count >= 3
        )
    }
    readiness_changed.emit(last_report)
    return last_report

extends Node3D
class_name TunisIntersectionSignalPass

var generated_count := 0
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2
var coordinator = null
var axis_zero_lamps: Array[MeshInstance3D] = []
var axis_one_lamps: Array[MeshInstance3D] = []
var pedestrian_axis_zero_lamps: Array[MeshInstance3D] = []
var pedestrian_axis_one_lamps: Array[MeshInstance3D] = []

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_signal_cluster(Vector3.ZERO)
    apply_visual_budget(current_detail_level)

func configure(value) -> void:
    coordinator = value
    _refresh_signal_faces()

func _process(_delta: float) -> void:
    _refresh_signal_faces()

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 1
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 2

func _register(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _material(color: Color, emissive := false) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = 0.72
    if emissive:
        material.emission_enabled = true
        material.emission = color
        material.emission_energy_multiplier = 2.2
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var node := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    node.mesh = mesh
    node.position = pos
    node.material_override = _material(color)
    parent.add_child(node)
    generated_count += 1
    return node

func _lamp(parent: Node3D, pos: Vector3, axis: int) -> MeshInstance3D:
    var node := MeshInstance3D.new()
    var mesh := SphereMesh.new()
    mesh.radius = 0.16
    mesh.height = 0.32
    node.mesh = mesh
    node.position = pos
    node.material_override = _material(Color("#b91f2d"), true)
    parent.add_child(node)
    generated_count += 1
    if axis == 0:
        axis_zero_lamps.append(node)
    else:
        axis_one_lamps.append(node)
    return node

func _pedestrian_lamp(parent: Node3D, pos: Vector3, crossing_axis: int) -> MeshInstance3D:
    var node := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = Vector3(0.22, 0.34, 0.12)
    node.mesh = mesh
    node.position = pos
    node.material_override = _material(Color("#b91f2d"), true)
    parent.add_child(node)
    generated_count += 1
    _register(node, 1)
    if crossing_axis == 0:
        pedestrian_axis_zero_lamps.append(node)
    else:
        pedestrian_axis_one_lamps.append(node)
    return node

func _build_signal_cluster(center: Vector3) -> void:
    var root := Node3D.new()
    root.name = "IntersectionSignals"
    add_child(root)
    var placements := [
        {"pos": center + Vector3(-9.0, 0.0, -9.0), "axis": 0},
        {"pos": center + Vector3(9.0, 0.0, 9.0), "axis": 0},
        {"pos": center + Vector3(-9.0, 0.0, 9.0), "axis": 1},
        {"pos": center + Vector3(9.0, 0.0, -9.0), "axis": 1}
    ]
    for placement in placements:
        var pos: Vector3 = placement["pos"]
        var axis: int = int(placement["axis"])
        _box(root, pos + Vector3(0, 2.15, 0), Vector3(0.16, 4.3, 0.16), Color("#303334"))
        var head := _box(root, pos + Vector3(0, 4.15, 0), Vector3(0.58, 1.15, 0.48), Color("#1d2021"))
        _register(head, 1)
        _lamp(root, pos + Vector3(0, 4.35, -0.27 if axis == 0 else 0.27), axis)
        _pedestrian_lamp(root, pos + Vector3(0.38, 2.35, 0), 1 - axis)
        var visor := _box(root, pos + Vector3(0, 4.57, -0.31 if axis == 0 else 0.31), Vector3(0.42, 0.12, 0.2), Color("#171919"))
        _register(visor, 2)

func _refresh_signal_faces() -> void:
    var active_axis := -1
    var phase_state := "all_red"
    if coordinator != null and coordinator.has_method("current_signal_state"):
        var signal_state: Dictionary = coordinator.current_signal_state()
        active_axis = int(signal_state.get("axis", -1))
        phase_state = str(signal_state.get("state", "all_red"))
    elif coordinator != null and coordinator.has_method("current_green_axis"):
        active_axis = int(coordinator.current_green_axis())
        phase_state = "green" if active_axis >= 0 else "all_red"

    _set_vehicle_axis_material(axis_zero_lamps, active_axis, 0, phase_state)
    _set_vehicle_axis_material(axis_one_lamps, active_axis, 1, phase_state)

    var pedestrian_zero_green := phase_state == "green" and active_axis == 0
    var pedestrian_one_green := phase_state == "green" and active_axis == 1
    _set_binary_material(pedestrian_axis_zero_lamps, pedestrian_zero_green)
    _set_binary_material(pedestrian_axis_one_lamps, pedestrian_one_green)

func _set_vehicle_axis_material(lamps: Array[MeshInstance3D], active_axis: int, lamp_axis: int, phase_state: String) -> void:
    var color := Color("#b91f2d")
    if active_axis == lamp_axis and phase_state == "green":
        color = Color("#35c15b")
    elif active_axis == lamp_axis and phase_state == "yellow":
        color = Color("#f4c542")
    for lamp in lamps:
        if is_instance_valid(lamp):
            lamp.material_override = _material(color, true)

func _set_binary_material(lamps: Array[MeshInstance3D], green: bool) -> void:
    var color := Color("#35c15b") if green else Color("#b91f2d")
    for lamp in lamps:
        if is_instance_valid(lamp):
            lamp.material_override = _material(color, true)

extends Node3D
class_name TunisNeighborhoodIdentityPass

var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_street_plaques()
    _build_house_numbers()
    _build_corner_markers()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    for node in medium_detail_nodes:
        if is_instance_valid(node): node.visible = current_detail_level >= 1
    for node in high_detail_nodes:
        if is_instance_valid(node): node.visible = current_detail_level >= 2

func _register(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2: high_detail_nodes.append(node)
    elif minimum_level == 1: medium_detail_nodes.append(node)
    return node

func _mat(color: Color) -> StandardMaterial3D:
    var m := StandardMaterial3D.new(); m.albedo_color = color; m.roughness = 0.88; return m

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var n := MeshInstance3D.new(); var mesh := BoxMesh.new(); mesh.size = size
    n.mesh = mesh; n.position = pos; n.material_override = _mat(color); parent.add_child(n); return n

func _label(parent: Node3D, text: String, pos: Vector3, size := 0.0065) -> Label3D:
    var l := Label3D.new(); l.text = text; l.position = pos; l.font_size = 40; l.pixel_size = size
    l.outline_size = 5; l.billboard = BaseMaterial3D.BILLBOARD_ENABLED; parent.add_child(l); return l

func _build_street_plaques() -> void:
    var root := Node3D.new(); root.name = "NeighborhoodStreetPlaques"; add_child(root)
    var plaques = [[Vector3(-48,3.0,-59.5),"نهج قرطاج / RUE DE CARTHAGE"],[Vector3(48,3.0,59.5),"نهج الحبيب بورقيبة / AV. H. BOURGUIBA"]]
    for item in plaques:
        _box(root,item[0],Vector3(5.5,1.0,0.12),Color("#245b87")); _label(root,item[1],item[0]+Vector3(0,0,0.08))

func _build_house_numbers() -> void:
    var root := Node3D.new(); root.name = "NeighborhoodHouseNumbers"; add_child(root); _register(root,1)
    var numbers = [[Vector3(-84,2.1,-73.9),"12"],[Vector3(-29,2.1,-73.9),"28"],[Vector3(29,2.1,-73.9),"41"],[Vector3(84,2.1,-73.9),"57"]]
    for item in numbers:
        _box(root,item[0],Vector3(0.8,0.6,0.1),Color("#e8e1cf")); _label(root,item[1],item[0]+Vector3(0,0,0.07),0.005)

func _build_corner_markers() -> void:
    var root := Node3D.new(); root.name = "NeighborhoodCornerMarkers"; add_child(root); _register(root,2)
    for p in [Vector3(-67.5,1.4,-67.5),Vector3(67.5,1.4,67.5)]:
        _box(root,p,Vector3(0.35,2.8,0.35),Color("#f0eee5"))
        _box(root,p+Vector3(0,1.2,0),Vector3(1.8,0.45,1.8),Color("#b92f2b"))
